function cleanIds(value) {
    if (!Array.isArray(value))
        return [];
    const ids = new Set();
    for (const item of value) {
        if (typeof item !== "string")
            continue;
        const id = item.trim().toLowerCase();
        if (id)
            ids.add(id);
    }
    return [...ids];
}
export function normalizeMcpIntegrationsConfig(input = true) {
    if (input === false ||
        (input &&
            typeof input === "object" &&
            input.enabled === false)) {
        return {
            enabled: false,
            custom: false,
            defaults: { enabled: false, exclude: [] },
        };
    }
    if (input === true || input === undefined) {
        return {
            enabled: true,
            custom: true,
            defaults: { enabled: true, exclude: [] },
        };
    }
    const defaults = input.defaults;
    const custom = input.custom !== false;
    const defaultsEnabled = defaults && typeof defaults === "object"
        ? defaults.enabled !== false
        : defaults !== false;
    if (!defaultsEnabled) {
        return {
            enabled: custom,
            custom,
            defaults: { enabled: false, exclude: [] },
        };
    }
    const include = defaults && typeof defaults === "object" ? cleanIds(defaults.include) : [];
    const exclude = defaults && typeof defaults === "object" ? cleanIds(defaults.exclude) : [];
    return {
        enabled: true,
        custom,
        defaults: {
            enabled: defaultsEnabled,
            ...(include.length > 0 ? { include } : {}),
            exclude,
        },
    };
}
